#!/usr/bin/env python3
"""Exercise the production editor in an invisible AppKit window (macOS only)."""
from pathlib import Path
import subprocess
import tempfile

root = Path(__file__).resolve().parent.parent
harness = r'''
import AppKit
import SwiftUI

// Theme's resource accessor is generated by SwiftPM; this check never uses BrandMark.
extension Bundle { static var module: Bundle { .main } }
NSApplication.shared.setActivationPolicy(.prohibited)

func descendant<T: NSView>(_ view: NSView, _ type: T.Type) -> T? {
    if let result = view as? T { return result }
    return view.subviews.compactMap { descendant($0, type) }.first
}

for text in [String(repeating: "整理今天的想法，检查记录输入体验。", count: 30),
             String(repeating: "Review the editor and record what happened. ", count: 30),
             "https://example.com/" + String(repeating: "unbroken-path", count: 100),
             "第一行\nSecond line\n第三行"] {
    let host = NSHostingView(rootView: JournalTextEditor(text: .constant(text), placeholder: "", focused: .constant(false)))
    let window = NSWindow(contentRect: NSRect(x: 0, y: 0, width: 400, height: 180),
                          styleMask: [.borderless], backing: .buffered, defer: false)
    window.contentView = host
    func settle() {
        for _ in 0..<5 {
            host.layoutSubtreeIfNeeded()
            RunLoop.main.run(until: Date().addingTimeInterval(0.01))
        }
    }
    settle()
    let scroll = descendant(host, NSScrollView.self)!
    let editor = scroll.documentView as! NSTextView
    let layout = editor.layoutManager!, container = editor.textContainer!
    func lines() -> Int {
        layout.ensureLayout(for: container)
        assert(abs(editor.frame.width - scroll.contentSize.width) < 1, "Editor exceeds visible width")
        var count = 0
        layout.enumerateLineFragments(forGlyphRange: layout.glyphRange(for: container)) { _, used, _, _, _ in
            assert(used.maxX <= container.size.width + 1, "Text extends past the wrapping boundary")
            count += 1
        }
        return count
    }
    let wideLines = lines()
    assert(wideLines >= 3, "Long text or explicit newlines did not wrap")
    let selected = NSRange(location: 2, length: 3)
    editor.setSelectedRange(selected)
    window.setContentSize(NSSize(width: 240, height: 180))
    settle()
    let narrowLines = lines()
    assert(narrowLines >= wideLines && (text.contains("\n") || narrowLines > wideLines), "Narrowing did not reflow text")
    assert(editor.string == text && editor.selectedRange() == selected, "Resize changed text or selection")
    if narrowLines > 10 {
        editor.scrollRangeToVisible(NSRange(location: text.utf16.count - 1, length: 1))
        assert(scroll.documentVisibleRect.minY > 0 && scroll.documentVisibleRect.minX == 0, "Long text cannot scroll vertically")
    }
    editor.undoManager!.beginUndoGrouping()
    editor.insertText("replacement", replacementRange: selected)
    editor.undoManager!.endUndoGrouping()
    editor.undoManager!.undo()
    assert(editor.string == text && editor.selectedRange() == selected, "Undo did not restore text and selection")
    editor.setMarkedText("拼音输入", selectedRange: NSRange(location: 0, length: 4), replacementRange: selected)
    let marked = editor.markedRange()
    window.setContentSize(NSSize(width: 520, height: 180))
    settle()
    assert(lines() <= narrowLines, "Widening did not reflow text")
    assert(editor.hasMarkedText() && editor.markedRange() == marked, "Resize interrupted input composition")
    editor.unmarkText()
}
print("PASS: Chinese, English, URLs, newlines, resize, scrolling, selection, undo and composition")
'''

with tempfile.TemporaryDirectory(prefix="justnow-editor-check-") as directory:
    work = Path(directory)
    main = work / "main.swift"
    main.write_text(harness)
    subprocess.run([
        "xcrun", "swiftc", "-swift-version", "5", "-parse-as-library",
        str(root / "Sources/JustNowCore/CalendarSelection.swift"),
        "-emit-module", "-emit-object", "-module-name", "JustNowCore",
        "-emit-module-path", str(work / "JustNowCore.swiftmodule"), "-o", str(work / "Core.o"),
    ], check=True)
    binary = work / "check"
    subprocess.run([
        "xcrun", "swiftc", "-swift-version", "5", "-I", directory,
        str(root / "Sources/JustNow/Controls.swift"), str(root / "Sources/JustNow/Theme.swift"),
        str(work / "Core.o"), str(main), "-o", str(binary),
    ], check=True)
    subprocess.run([str(binary)], check=True)
